CREATE DATABASE IF NOT EXISTS seckill_product DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE seckill_product;
CREATE TABLE IF NOT EXISTS products(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(200) NOT NULL,title VARCHAR(200),description VARCHAR(2000),images TEXT,price DECIMAL(10,2) NOT NULL,stock INT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
